/* Perfect Rattlesnake 29 by Cornerstone-04 — https://uiverse.io/Cornerstone-04/perfect-rattlesnake-29 */
.card {
  width: 160px;
  height: 200px;
  background: #ffffff;
  transform: rotate(20deg) skew(-10deg, -5deg);
  transition: .4s linear;
  display: flex;
  justify-content: center;
  align-items: center;
  text-align: center;
  font-size: 1.2rem;
  font-weight: 700;
  line-height: 200px;
}

.card:hover {
  box-shadow: rgba(0,0,0,0.5) 5px 3px,
  rgba(0,0,0,0.4) 10px 6px,
  rgba(0,0,0,0.3) 15px 9px;
  background: #000;
  color: #fff;
  font-size: 1.5rem;
}
